# The following code implements a solution to the N-Queens problem using Python's built-in list and set data structures.

# Explanation of Pruning Strategy: During the recursive backtracking process, we prune branches early by ensuring no queens threaten each other in rows, columns, or diagonals before proceeding further. This is achieved through the check_conflict function which checks for conflicts with already placed queens.

# Worst-case time complexity is O(N!) because there are N! possible solutions (since each queen can be placed in any of N positions), and the algorithm must explore all of them to find a valid solution.

from itertools import permutations

class NQueens:
    def __init__(self, n):
        self.n = n
        self.solutions = set()
        self.valid_solutions = []

    def solve(self, row=0):
        if row == self.n:
            # A solution is found when all queens are placed without conflicts
            board = list(permutations(range(self.n)))
            for perm in board:
                if self.check_conflict(perm, row): 
                    self.valid_solutions.append(list(perm))
            return len(self.valid_solutions) > 0
        else:
            # Place a queen on the current row and try to solve the rest of the rows
            for col in range(self.n):
                if not self.check_conflict([row, col], row):
                    continue  # Skip this column as it is already conflicting with some other queens.
                board = list(range(self.n))
                board[row] = col
                if self.solve(row + 1):
                    break  # If the rest of the rows can be solved without conflicts, add to solutions set.
            return False

    def check_conflict(self, placement, row):
        col = placement[1]
        for i in range(len(placement) - 1): 
            if col == placement[i] or abs(row - i) == abs(col - placement[i]):
                return True
        return False

# Usage:
solver = NQueens(n=4)
if solver.solve():
    print(solver.valid_solutions)
else:
    print('No solutions found.')

